# Validate count
print(f"Total words generated: {len(data)}")

# Check for duplicates
words = [item["Word"] for item in data]
duplicates = [w for w in words if words.count(w) > 1]
if duplicates:
    unique_dupes = list(set(duplicates))
    print(f"WARNING: Found duplicate words: {unique_dupes}")
    # Remove duplicates, keep first occurrence
    seen = set()
    deduped = []
    for item in data:
        if item["Word"] not in seen:
            seen.add(item["Word"])
            deduped.append(item)
    data = deduped
    print(f"After deduplication: {len(data)} words")

# Verify all are Tier 3
non_tier3 = [item for item in data if item["Tier"] != "3-고급"]
if non_tier3:
    print(f"WARNING: {len(non_tier3)} items are not Tier 3")

